/**
 * The e2e-verifier's browser check, run by `hooks/edge-cdp.js` on every browser-use tool call: a pattern
 * check on the code it sends (defense in depth, not a sandbox). Only an `agent_type` of `e2e-verifier` is
 * checked; it may drive localhost pages and read, nothing else: no remote browser, no foreign host, no
 * shell, no file write, no obfuscated code. Pure; any error means no deny, logged.
 *
 * Generated by Claude Code at the user's request.
 */

'use strict';

const { logError } = require('./cache');

const LOCAL_HOST = /^(?:localhost|127\.0\.0\.1|\[::1\]|host\.docker\.internal|[^.]+(?:\.[^.]+)*\.localhost)$/i;
const URL_HOST = /\b(?:https?|wss?):\/\/([^\s/'"?#\\)>]+)/gi;
const FORBIDDEN = [
  [/\bstart_remote_daemon\b/, 'a remote browser (`start_remote_daemon`)'],
  [/subprocess|\bos\.(?:system|popen|remove|unlink|rename|replace|rmdir|removedirs|startfile|exec\w*|spawn\w*|posix_spawn\w*)\b|\bshutil\b|\bfrom\s+os\s+import\b/,
    'a shell, a process or a file removal (`subprocess`, `os.system`, `os.exec*`, `os.spawn*`, `os.remove`, `shutil`, `from os import`)'],
  [/\.(?:write_text|write_bytes|unlink)\s*\(/, 'a file write (`write_text`, `write_bytes`, `unlink`)'],
  [/\bopen\s*\(.*?,\s*(?:mode\s*=\s*)?['"][rbtU]*[wax+][rbtU+]*['"]/, 'a file opened for writing (`open(` with a mode containing w, a, x or +)'],
  [/\b(?:exec|eval)\s*\(|__import__/, 'obfuscated code (`exec(`, `eval(`, `__import__`)'],
];

/** The host of a URL's authority: no userinfo, no port. */
function hostOf(authority) {
  const host = authority.slice(authority.lastIndexOf('@') + 1);
  return host.startsWith('[') ? host.slice(0, host.indexOf(']') + 1) : host.replace(/:\d*$/, '');
}

function check(payload) {
  if (payload?.agent_type !== 'e2e-verifier') return null;
  const tool = String(payload.tool_name ?? '');
  if (tool.endsWith('__browser_login')) return { reason: 'e2e-verifier may not call browser_login: it works on a local browser, and a login belongs to the caller.' };

  const code = Object.values(payload.tool_input ?? {}).filter((value) => typeof value === 'string').join('\n');
  const forbidden = FORBIDDEN.find(([pattern]) => pattern.test(code));
  if (forbidden) return { reason: `e2e-verifier may not use ${forbidden[1]} in browser code. Report the step as not-run instead.` };
  const foreign = [...code.matchAll(URL_HOST)].map((match) => hostOf(match[1])).find((host) => !LOCAL_HOST.test(host));
  if (foreign) return { reason: `e2e-verifier may only reach localhost, 127.0.0.1, [::1], host.docker.internal or *.localhost, not '${foreign}'. Report the step as not-run instead.` };
  return null;
}

/** `{ reason }` when this e2e-verifier browser call must be denied, else null. */
function checkE2eBrowser(payload) {
  try {
    return check(payload);
  } catch (error) {
    logError('e2e-browser', error);
    return null;
  }
}

module.exports = { checkE2eBrowser };
